namespace Harness.Core.Instructions;

public static class AgentGuidance
{
    public const string FileName = "AGENTS.md";
    public const string ClaudeFileName = "CLAUDE.md";
    public const string Marker = "<!-- BEGIN harness";
    public const string EndMarker = "<!-- END harness -->";
    public const string BeginMarker =
        "<!-- BEGIN harness (generated by 'harness instructions'; edit outside this block) -->";
    public static MarkedBlock Block { get; } = new(Marker, EndMarker, "harness section");
    public static string ImportBlock => BeginMarker + "\n@AGENTS.md\n" + EndMarker;
    public static string Section =>
        BeginMarker + "\n" + Body.Replace("\r\n", "\n", StringComparison.Ordinal) + "\n" + EndMarker;

    public static bool ImportsItself(string source)
    {
        var (start, end) = Block.Find(source);
        if (start >= 0)
        {
            source = source[..start] + source[end..];
        }

        return source.Split('\n').Any(line => line.Trim() is "@AGENTS.md" or "@./AGENTS.md");
    }

    public const string Body = """
        ## Harness

        This repository uses **harness**, a local MCP server (`harness`) holding project state shared by all agents.

        - Start a task with `get_context` (the task in words, naming known symbols); then drill down with
          `search_project` (kind `impact` before changing a symbol), targeted reads and `package_api`, not whole directories.
          Other workspace repositories: `scope` workspace; keep `depth` light unless the user asks for compiler-exact cross-project answers.
        - Before planning read `goals_current` and `constraints_current`; before changing an area, `decisions_for` it.
          An `open_question` is the user's to settle: ask.
        - Architecture findings (`architecture_findings`, `get_context`): explain and suggest; act only once it is a task. Propose, never create, tasks (`architecture_propose`, else `task_propose`) and blueprints (`task_blueprint_propose`); set their `approved_by` only when the user or a recorded process already approved that work outside harness.
        - For planned work, take one task with `task_next` (claim=true) and keep its `claim_token`; it stays `claimed` while
          you analyse and clarify. `task_update` it to `in_progress` when you start changing code, and to `review` while you
          check the acceptance criteria, constraints and validation (back to `in_progress` if something fails). Finish with
          `task_complete` reporting every acceptance criterion and the validation you ran.
        - Record settled goals, constraints, decisions, conventions and warnings with `memory_put` (one short statement, with
          `source_ref`), including a task's durable decisions at the end of a task; what the user has not confirmed goes to `memory_propose` (or
          `proposals` of `task_complete`). Never store transcripts, code or temporary notes; if a decision changes, `memory_supersede` it.
        - Merge requests on the project's SCM (GitLab, Forgejo, GitHub): the `scm_` tools act on this project's merge requests by
          their number. To review one, read `scm_get_merge_request_details`, `scm_get_merge_request_diff` and
          `scm_get_merge_request_comments` first (list them with `scm_list_merge_requests`); leave one
          `scm_add_merge_request_diff_comment` per concrete finding on its changed line (`line_type` old for a removed line)
          and the summary with `scm_add_merge_request_comment`. Change a title or description, approve, or open a merge request
          (`scm_create_merge_request`, from a pushed branch) only when the user asks.
        - If harness tools are missing or failing (including an `scm_` tool saying no SCM matches), run `harness doctor` and report its output.
        """;
}
